@using sv_bf0e93df8c9447f59f1513b866e6209b.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label for="warehouse-select"><strong>Warehouse:</strong></label>
    <select id="warehouse-select" class="form-select form-select-sm" style="width: auto; display: inline-block;"
            value="@WarehouseState.CurrentWarehouseId" @onchange="OnWarehouseSelected">
        @foreach (var wh in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleStateChanged;
    }

    private void OnWarehouseSelected(ChangeEventArgs e)
    {
        var selected = e.Value?.ToString();
        if (!string.IsNullOrEmpty(selected))
        {
            WarehouseState.SetWarehouse(selected);
        }
    }

    private void HandleStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= HandleStateChanged;
    }
}

