@page "/dashboard"
@using sv_bf0e93df8c9447f59f1513b866e6209b.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-3">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text fs-4">@GetWarehouseName()</p>
    </div>
</div>

<div class="card mb-3">
    <div class="card-body">
        <h5 class="card-title">Low Stock Alerts</h5>
        <p class="card-text">
            <span class="fs-2">
                @if (AlertService.CurrentLowStockCount > 0)
                {
                    <span class="text-danger fw-bold">@AlertService.CurrentLowStockCount</span>
                }
                else
                {
                    <span class="text-success fw-bold">0</span>
                }
            </span>
            <span class="text-muted ms-2">items below minimum level</span>
        </p>
        <small class="text-muted">Auto-refreshes every 10 seconds</small>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        // Subscribe to start polling while this page is visible
        AlertService.Subscribe();

        WarehouseState.OnWarehouseChanged += HandleStateChanged;
        AlertService.OnAlertDataChanged += HandleStateChanged;
    }

    private void HandleStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetWarehouseName()
    {
        var wh = WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId);
        return wh == default ? WarehouseState.CurrentWarehouseId : wh.Name;
    }

    public void Dispose()
    {
